try { out("types.isDate(X) | undefined", types.isDate((undefined))); } catch (error) { out("types.isDate(X) | undefined", error.constructor.name); }
try { const x = mix(undefined); if (types.isDate(x)) out("  yes", `${typeof x} ${t(() => x.length)} ${t(() => x.name)} ${t(() => x.size)} ${t(() => x.message)} ${t(() => x.getTime)} ${t(() => typeof (x + 1))} ${t(() => x[0])}`); else out("  no", `${typeof x} ${t(() => x.length)} ${t(() => x.name)} ${t(() => x.size)} ${t(() => x.message)} ${t(() => x.getTime)} ${t(() => typeof (x + 1))} ${t(() => x[0])}`); } catch (error) { out("  neither", error.constructor.name); }
